import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useLanguage } from '../../context/LanguageContext';
import { useTheme } from '../../context/ThemeContext';
import Button from '../../components/common/Button/Button';
import advertService from '../../services/advertService';
import locationService from '../../services/locationService';
import styles from './AdvertDetailsPage.module.css';

const AdvertDetailsPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { user, isAuthenticated } = useAuth();
    const { t, language } = useLanguage();
    const { theme } = useTheme();

    const [advert, setAdvert] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [isParticipating, setIsParticipating] = useState(false);

    const [showMap, setShowMap] = useState(false);
    const [mapLoading, setMapLoading] = useState(false);

    const mapRef = useRef(null);
    const mapInstanceRef = useRef(null);

    useEffect(() => {
        loadAdvert();
        return () => {
            if (mapInstanceRef.current) {
                mapInstanceRef.current.destroy();
            }
        };
    }, [id]);

    const loadAdvert = async () => {
        try {
            const response = await advertService.getAdvertById(id);
            setAdvert(response.advert);
            if (user && response.advert.participatingUserIds) {
                setIsParticipating(response.advert.participatingUserIds.split(',').includes(user.id.toString()));
            }
        } catch (err) {
            setError(t('loadError'));
        } finally {
            setLoading(false);
        }
    };

    const loadYandexMaps = () => {
        return new Promise((resolve) => {
            if (window.ymaps) {
                window.ymaps.ready(resolve);
                return;
            }
            const script = document.createElement('script');
            const lang = language === 'ru' ? 'ru_RU' : 'en_EN';
            script.src = `https://api-maps.yandex.ru/2.1/?lang=${lang}`;
            script.async = true;
            script.onload = () => {
                window.ymaps.ready(resolve);
            };
            document.head.appendChild(script);
        });
    };

    const initMap = (lat, lon, address) => {
        if (mapRef.current && window.ymaps) {
            // Уничтожаем старую карту
            if (mapInstanceRef.current) {
                mapInstanceRef.current.destroy();
                mapInstanceRef.current = null;
            }

            // Очищаем контейнер
            mapRef.current.innerHTML = '';

            const map = new window.ymaps.Map(mapRef.current, {
                center: [lat, lon],
                zoom: 16,
                controls: ['zoomControl', 'fullscreenControl']
            });

            const placemark = new window.ymaps.Placemark([lat, lon], {
                hintContent: address,
                balloonContent: address
            }, {
                preset: 'islands#redIcon',
                draggable: false
            });

            map.geoObjects.add(placemark);
            mapInstanceRef.current = map;
        }
    };

    const loadMap = async () => {
        if (!advert?.address) return;

        // Если карта уже показана, просто выходим
        if (showMap && mapInstanceRef.current) return;

        setMapLoading(true);
        setShowMap(true);

        try {
            const coords = await locationService.getAddressCoordinates(advert.address);
            if (coords) {
                await loadYandexMaps();
                setTimeout(() => {
                    initMap(coords.lat, coords.lon, advert.address);
                    setMapLoading(false);
                }, 100);
            } else {
                setError(t('mapLoadError') || 'Адрес не найден');
                setShowMap(false);
                setMapLoading(false);
            }
        } catch (err) {
            console.error('Error loading map:', err);
            setError(t('mapLoadError') || 'Ошибка загрузки карты');
            setShowMap(false);
            setMapLoading(false);
        }
    };

    const handleCloseMap = () => {
        if (mapInstanceRef.current) {
            mapInstanceRef.current.destroy();
            mapInstanceRef.current = null;
        }
        setShowMap(false);
    };

    const handleSubscribe = async () => {
        if (!isAuthenticated) { navigate('/login'); return; }
        try {
            if (isParticipating) await advertService.unsubscribeFromAdvert(id);
            else await advertService.subscribeToAdvert(id);
            await loadAdvert();
        } catch (err) { alert(err.message); }
    };

    const formatDate = (dateStr) => {
        if (!dateStr) return '';
        const date = new Date(dateStr);
        const options = language === 'ru'
            ? { day: 'numeric', month: 'long', year: 'numeric' }
            : { month: 'long', day: 'numeric', year: 'numeric' };
        const formatted = date.toLocaleDateString(language === 'ru' ? 'ru-RU' : 'en-US', options);
        return language === 'ru' ? `${formatted} г.` : formatted;
    };

    const formatTime = (timeStr) => {
        if (!timeStr) return '';
        return timeStr.substring(0, 5);
    };

    const getGameLevelName = (level) => {
        const levelMap = {
            1: 'D1', 2: 'D2', 3: 'D3', 4: 'D4', 5: 'D4+',
            'D1': 'D1', 'D2': 'D2', 'D3': 'D3', 'D4': 'D4', 'D4Plus': 'D4+'
        };
        return levelMap[level] || 'D2';
    };

    const isCreator = user && advert?.userId === user.id;

    if (loading) return <div className={styles.loading}>{t('loading')}</div>;
    if (error) return <div className={styles.error}>{error}</div>;
    if (!advert) return null;

    const isFull = advert.participantsCount >= advert.peopleCount;
    const participantsCount = advert.participantsCount || 0;
    const levelName = getGameLevelName(advert.gameLevel);

    return (
        <div className={styles.detailsPage}>
            <div className={styles.container}>
                <button className={styles.backButton} onClick={() => navigate(-1)}>← {t('back')}</button>

                <div className={styles.card}>
                    <div className={styles.header}>
                        <div className={styles.levelBadge}>
                            {t('gameLevel')} {levelName}
                        </div>
                        {isCreator && <div className={styles.creatorBadge}>{t('yourAdvert')}</div>}
                    </div>

                    <div className={styles.content}>
                        <div className={styles.section}>
                            <div className={styles.sectionLabel}>{t('location')}</div>
                            <div className={styles.sectionValue}>{advert.address}</div>
                            <button className={styles.mapButton} onClick={loadMap}>
                                🗺️ {t('map')}
                            </button>
                        </div>

                        {showMap && (
                            <div className={styles.mapContainer}>
                                {mapLoading && <div className={styles.mapLoading}>{t('loading')}</div>}
                                <div
                                    ref={mapRef}
                                    className={styles.map}
                                    style={{
                                        display: mapLoading ? 'none' : 'block',
                                        height: '400px',
                                        width: '100%'
                                    }}
                                ></div>
                                <button className={styles.closeMapButton} onClick={handleCloseMap}>
                                    ✕ {t('closeMap')}
                                </button>
                            </div>
                        )}

                        <div className={styles.infoGrid}>
                            <div className={styles.section}>
                                <div className={styles.sectionLabel}>{t('date')}</div>
                                <div className={styles.sectionValue}>{formatDate(advert.date)}</div>
                            </div>
                            <div className={styles.section}>
                                <div className={styles.sectionLabel}>{t('time')}</div>
                                <div className={styles.sectionValue}>
                                    {formatTime(advert.startTime)} - {formatTime(advert.endTime)}
                                </div>
                            </div>
                            <div className={styles.section}>
                                <div className={styles.sectionLabel}>{t('participants')}</div>
                                <div className={styles.sectionValue}>{participantsCount} / {advert.peopleCount}</div>
                            </div>
                            <div className={styles.section}>
                                <div className={styles.sectionLabel}>{t('cost')}</div>
                                <div className={styles.sectionValue}>{advert.cost} BYN</div>
                            </div>
                        </div>

                        {advert.description && (
                            <div className={styles.section}>
                                <div className={styles.sectionLabel}>{t('description')}</div>
                                <div className={styles.sectionValue}>{advert.description}</div>
                            </div>
                        )}
                    </div>

                    <div className={styles.footer}>
                        {isCreator ? (
                            <div className={styles.creatorActions}>
                                <Button variant="outline" onClick={() => navigate(`/add-advert?edit=${advert.id}`)}>
                                    {t('edit')}
                                </Button>
                                <Button variant="danger" onClick={async () => {
                                    if (window.confirm(t('confirmDelete'))) {
                                        try {
                                            await advertService.deleteAdvert(id);
                                            navigate('/');
                                        } catch (err) { alert(err.message); }
                                    }
                                }}>
                                    {t('delete')}
                                </Button>
                            </div>
                        ) : (
                            <Button
                                fullWidth
                                variant={isParticipating ? 'secondary' : 'primary'}
                                onClick={handleSubscribe}
                                disabled={!isParticipating && isFull}
                            >
                                {isParticipating ? t('unsubscribe') : (isFull ? t('noSeats') : t('subscribe'))}
                            </Button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AdvertDetailsPage;
